<?php
declare(strict_types=1);
require_once __DIR__ . '/../admin/_common.php';
require_once __DIR__ . '/../config/database.php';
$isAdmin=isset($_SESSION['admin_user_id'])&&($_SESSION['admin_user_type']??'')==='admin'&&($_SESSION['admin_2fa_verified']??false)===true;
function normalizePaintingImageUrl($url){$url=(string)$url;if($url==='')return null;$legacy='paintings/uploads/';$current='/paintings/uploads/';if(str_starts_with($url,$legacy))return $current.substr($url,strlen($legacy));return $url;}
try{$id=isset($_GET['id'])?(int)$_GET['id']:0;if($id<=0)adminJsonResponse(['success'=>false,'message'=>'Invalid painting ID'],400);$sql='SELECT p.id,p.artist_id,p.category_id,p.name,p.slug,p.description,p.price,p.discount_price,p.width,p.height,p.medium,p.frame,p.gold_details,p.stock,p.is_featured,p.is_active,p.created_at,p.updated_at,c.name AS category_name FROM paintings p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?';if(!$isAdmin)$sql.=' AND p.is_active=1';$sql.=' LIMIT 1';$stmt=$pdo->prepare($sql);$stmt->execute([$id]);$painting=$stmt->fetch(PDO::FETCH_ASSOC);if(!$painting)adminJsonResponse(['success'=>false,'message'=>'Painting not found'],404);$sizeStmt=$pdo->prepare('SELECT id,name,width,height,unit,price,is_standard,sort_order FROM painting_size_options WHERE painting_id=? ORDER BY sort_order ASC,id ASC');$sizeStmt->execute([$id]);$rawSizes=$sizeStmt->fetchAll(PDO::FETCH_ASSOC);$uniqueSizes=[];foreach($rawSizes as $size){$key=strtolower(trim((string)$size['name'])).'|'.number_format((float)$size['width'],2,'.','').'|'.number_format((float)$size['height'],2,'.','').'|'.strtolower(trim((string)$size['unit'])).'|'.number_format((float)$size['price'],2,'.','');if(isset($uniqueSizes[$key]))continue;$size['id']=(int)$size['id'];$size['is_standard']=(int)$size['is_standard'];$uniqueSizes[$key]=$size;}$painting['size_options']=array_values($uniqueSizes);$imageStmt=$pdo->prepare('SELECT id,image_url,sort_order,is_primary FROM painting_images WHERE painting_id=? ORDER BY sort_order ASC,id ASC');$imageStmt->execute([$id]);$painting['images']=$imageStmt->fetchAll(PDO::FETCH_ASSOC);foreach($painting['images'] as &$image)$image['image_url']=normalizePaintingImageUrl($image['image_url']);unset($image);$painting['image_url']=!empty($painting['images'])?$painting['images'][0]['image_url']:null;adminJsonResponse(['success'=>true,'painting'=>$painting]);}catch(Throwable $e){error_log('Painting get error: '.$e->getMessage());adminJsonResponse(['success'=>false,'message'=>'Unable to load painting'],500);}
